// 代表题「并发 2」：第 i 号线程先 acquire 自己的门，打印 i+1，再 release 下一扇门。
// 许可会积攒，所以某一号还没 start 时前一号已经 release 也不会丢唤醒、也不会乱序。
// 换题只改 println 的内容；n 改成线程个数。奇偶行交替不要用这条单链，改成 turn + wait。
static void print1ToN(int n) {
    Semaphore[] go = new Semaphore[n];
    Thread[] ts = new Thread[n];
    for (int i = 0;
    i < n;
    i++) go[i] = new Semaphore(0);
    for (int i = 0;
    i < n;
    i++) {
        final int idx = i;
        ts[i] = new Thread(() -> {
            try {
                go[idx].acquire();
                System.out.println(idx + 1);
                if (idx + 1 < n) go[idx + 1].release();
            }
            catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        );
    }
    for (Thread t : ts) t.start();
    go[0].release();
    for (Thread t : ts) {
        try {
            t.join();
        }
        catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

